<?php
namespace App\Jobs;
use App\Domain\Audit\Services\AuditRecorder;use App\Domain\Documents\Services\AuthorizedDocumentQuery;use App\Models\{ExportLog,User};use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Queue\Queueable;use Illuminate\Support\Facades\Storage;use RuntimeException;
class GenerateDocumentExport implements ShouldQueue{use Queueable;public int $tries=2;public int $timeout=900;public function __construct(public int $exportLogId){$this->onQueue('exports');}public function handle(AuditRecorder $audit):void{$log=ExportLog::findOrFail($this->exportLogId);$user=User::findOrFail($log->user_id);$query=app(AuthorizedDocumentQuery::class)->for($user)->with(['barcode','documentType','district','revenueCircle']);$f=$log->filters??[];foreach(['district_id','revenue_circle_id','document_type_id','record_year','status'] as $field)if(!empty($f[$field]))$query->where($field,$f[$field]);$disk='local';$key='dms-exports/'.$log->ulid.'/documents.csv';$temp=tempnam(sys_get_temp_dir(),'dms-export-');$h=fopen($temp,'wb');fputcsv($h,['Reference','Barcode','Type','District','Revenue Circle','Patta','Dag','Record Year','Status']);$rows=0;$query->orderBy('id')->chunkById(1000,function($docs)use($h,&$rows){foreach($docs as $d){fputcsv($h,[$d->reference_no,$d->barcode?->barcode_value,$d->documentType?->name_en,$d->district?->name_en,$d->revenueCircle?->name_en,$d->patta_no,$d->dag_no,$d->record_year,$d->status->value]);$rows++;}});fclose($h);$stream=fopen($temp,'rb');Storage::disk($disk)->writeStream($key,$stream);fclose($stream);$sha=hash_file('sha256',Storage::disk($disk)->path($key));@unlink($temp);$log->update(['row_count'=>$rows,'status'=>'READY','storage_disk'=>$disk,'storage_key'=>$key,'sha256'=>$sha,'completed_at'=>now(),'expires_at'=>now()->addMinutes((int)env('DMS_EXPORT_TTL_MINUTES',60))]);$audit->record('EXPORT_READY','REPORTING','SUCCESS',$user,['context'=>['export_ulid'=>$log->ulid,'rows'=>$rows,'sha256'=>$sha]]);}public function failed(\Throwable $e):void{ExportLog::whereKey($this->exportLogId)->update(['status'=>'FAILED','error_message'=>$e->getMessage()]);}}
